import React, { useEffect, useState, useContext } from 'react';
import { Container, ListGroup, ListGroupItem, Spinner } from 'reactstrap';
import SockJS from 'sockjs-client';
import { Client } from '@stomp/stompjs';
import { DataContext } from '../../../context/DataContext';

const BASE_URL = 'http://localhost:8080'; // 실제 API URL을 넣으세요

const ChatList = () => {
    const [stompClient, setStompClient] = useState(null);
    const [chatsData, setChatsData] = useState([]);
    const { data } = useContext(DataContext);
    const { loginUser } = data || {}; // Ensure data is always an object
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const id = loginUser?.email;
        console.log(`useEffect - loginUser: ${JSON.stringify(loginUser)}`); // console.log 추가
        console.log(`useEffect - id: ${id}`); // console.log 추가
        if (id) {
            fetchChats(id);
        }

        const socket = new SockJS(`${BASE_URL}/ws`);
        const client = new Client({
            webSocketFactory: () => socket,
            debug: function (str) {
                console.log(`WebSocket debug: ${str}`); // console.log 추가
            },
            reconnectDelay: 5000,
        });

        client.onConnect = () => {
            console.log('WebSocket connected'); // console.log 추가
            setStompClient(client);
            client.subscribe('/topic/chats', (msg) => {
                if (msg.body) {
                    console.log(`Received message: ${msg.body}`); // console.log 추가
                    setChatsData(JSON.parse(msg.body));
                }
            });
        };

        client.activate();

        return () => {
            console.log('WebSocket disconnected'); // console.log 추가
            if (client) {
                client.deactivate();
            }
        };
    }, [loginUser]);

    const fetchChats = (id) => {
        console.log(`fetchChats - id: ${id}`); // console.log 추가
        fetch(`http://localhost:8080/api/chats?userId=${id}`)
            .then((response) => response.json())
            .then((data) => {
                console.log(`fetchChats - data: ${JSON.stringify(data)}`); // console.log 추가
                setChatsData(data);
                setLoading(false);
            })
            .catch((error) => {
                console.error('Error fetching chat data:', error); // console.error 추가
                setLoading(false);
            });
    };

    const handleItemPress = (chatId, otherUserId, last_message) => {
        alert(`Chat ID: ${chatId}, Other User ID: ${otherUserId}, Last Message: ${last_message}`);
    };

    const renderChatListItem = (item) => {
        console.log(`renderChatListItem - item: ${JSON.stringify(item)}`); // console.log 추가
        const otherUserId = item.from_id === loginUser?.email ? item.to_id : item.from_id;

        console.log(`renderChatListItem - otherUserId: ${otherUserId}`); // console.log 추가
        console.log(`renderChatListItem - last_message: ${item.last_message}`); // console.log 추가
        alert(`chatid : ${item.id}, otherUserId: ${otherUserId}, last_message: ${item.last_message}`);
        return (
            <ListGroupItem
                key={item.id}
                className="d-flex justify-content-between align-items-center"
                onClick={() => handleItemPress(item.id, otherUserId, item.last_message)}
                style={{ marginBottom: '5px' }}
            >
                <div>
                    <strong>너 : {otherUserId}</strong>
                    <p>최근 : {item.last_message}</p>
                    <small>{new Date(item.time).toLocaleString()}</small>
                </div>
            </ListGroupItem>
        );
    };

    return (
        <Container>
            {loading ? (
                <Spinner color="primary" />
            ) : chatsData.length > 0 ? (
                <ListGroup>{chatsData.map((item) => renderChatListItem(item))}</ListGroup>
            ) : (
                <div className="text-center">
                    <p>채팅 내역이 없습니다</p>
                    <p>id : {loginUser?.email}</p>
                </div>
            )}
        </Container>
    );
};

export default ChatList;
